function maxFreqSum(s) {
  const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
  const count = new Map();
  for (const letter of s) {
    count.set(letter, (count.get(letter) ?? 0) + 1);
  }

  let bestVowel = 0;
  let bestConsonant = 0;
  for (const [letter, freq] of count) {
    if (vowels.has(letter)) {
      bestVowel = Math.max(bestVowel, freq);
    } else {
      bestConsonant = Math.max(bestConsonant, freq);
    }
  }
  return bestVowel + bestConsonant;
}

