function maxFreqSum(s) {
  // Rescan the whole string for each of the 26 letters.
  let vowel = 0, consonant = 0;
  for (const letter of 'abcdefghijklmnopqrstuvwxyz') {
    let times = 0;
    for (let i = 0; i < s.length; i++) if (s[i] === letter) times++;
    if ('aeiou'.includes(letter)) vowel = Math.max(vowel, times);
    else consonant = Math.max(consonant, times);
  }
  return vowel + consonant;
}

