function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  // Small alphabets make repeats and ties common; some have no vowels or no consonants at all.
  const alphabets = ['abcdefghijklmnopqrstuvwxyz', 'aeiou', 'bcdfghjklmnpqrstvwxyz', 'ab', 'eyz', 'aeiouxy', 'ooz', 'y'];
  const letters = alphabets[pick(alphabets.length)];
  const length = size === 'large' ? 80 + pick(21) : 1 + pick(12);
  let s = '';
  for (let i = 0; i < length; i++) s += letters[pick(letters.length)];
  return [s];
}
